"""Load generated connector credentials through an explicit filesystem seam."""

import json

from collections.abc import Callable
from pathlib import Path

DEFINITION_INPUT_FILE = "data_diff.json"


class RuntimeConnectorConfigLoader:
    """Read source and target runtime JSON generated by PipelineWise.

    Generated connector configs may keep secrets as lookups, such as ``{{ env_var['NAME'] }}``.
    ``render`` turns a file's text into plain JSON before parsing. The CLI supplies it, so this
    package does not depend on the CLI's template helpers.
    """

    def __init__(self, config_dir: str, render: Callable[[str], str] | None = None):
        self.config_dir = Path(config_dir)
        self.render = render

    def _load(self, path: Path) -> dict:
        try:
            text = path.read_text(encoding="utf-8")
        except FileNotFoundError as exc:
            raise ValueError(
                f"Generated connector config does not exist: {path}. "
                "Run pipelinewise import_config first."
            ) from exc
        return json.loads(self.render(text) if self.render else text)

    def __call__(self, check: dict) -> tuple:
        """Return source and target connection dictionaries for one check."""
        target_dir = self.config_dir / check["target_id"]
        source_path = target_dir / check["tap_id"] / "config.json"
        target_path = target_dir / "config.json"
        return self._load(source_path), self._load(target_path)


def load_definition_input(config_dir: str, target_id: str, tap_id: str) -> dict:
    """Read the tap's generated data-diff definition input.

    The file holds only the configuration that data-diff definitions are built from, and no
    credentials. A missing file is an error rather than "no checks": syncing nothing would
    deactivate every definition of the tap.
    """
    path = Path(config_dir) / target_id / tap_id / DEFINITION_INPUT_FILE
    try:
        document = json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise ValueError(
            f"Data-diff definition input does not exist: {path}. "
            "Generate it with pipelinewise import_config, or with the tool that generates this tap's config."
        ) from exc
    target, tap = document.get("target"), document.get("tap")
    if not isinstance(target, dict) or not isinstance(tap, dict):
        raise ValueError(f"{path} must contain 'target' and 'tap' objects")
    if target.get("id") != target_id or tap.get("id") != tap_id:
        raise ValueError(
            f"{path} describes tap {tap.get('id')!r} in target {target.get('id')!r}, "
            f"not tap {tap_id!r} in target {target_id!r}"
        )
    return document
